#include <stdio.h>
#include <math.h>
typedef struct{float x,y,z;} V;
static V add(V a,V b){return(V){a.x+b.x,a.y+b.y,a.z+b.z};}
static V sub(V a,V b){return(V){a.x-b.x,a.y-b.y,a.z-b.z};}
static V mul(V a,float b){return(V){a.x*b,a.y*b,a.z*b};}
static float dot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
static V norm(V a){return mul(a,1/sqrtf(dot(a,a)));}
static int sph(V o,V d,float *t,V *n){V c={0,-.5,-5},q=sub(o,c);float b=2*dot(q,d),z=b*b-4*(dot(q,q)-1),r;if(z<0)return 0;r=(-b-sqrtf(z))/2;if(r<.001)r=(-b+sqrtf(z))/2;if(r<.001)return 0;*t=r;*n=norm(sub(add(o,mul(d,r)),c));return 1;}
static int shadow(V p,V l){float t;V n;return sph(p,l,&t,&n);}
static int plane(V o,V d,float *t){if(fabsf(d.y)<.001)return 0;*t=(-1.5-o.y)/d.y;return *t>.001;}
static int pix(float x){x=fmaxf(0,fminf(x,1))*255.99f;return(int)x;}
int main(void){int x,y;V l=norm((V){1,1,-1});FILE*f=fopen("image.ppm","w");fprintf(stderr,"Creating high-resolution image: 800x600\nThis will be downsampled with ffmpeg after rendering\nRendering high-resolution image...\n");fprintf(f,"P3\n800 600\n255\n");for(y=0;y<600;y++){fprintf(stderr,"\rProgress: %.1f%%",100.f*y/600);for(x=0;x<800;x++){V d=norm((V){2.6666667f*x/799-1.3333333f,1-2.f*y/599,-1});float ts,tp;V n,p,c;int hs=sph((V){0,0,0},d,&ts,&n),hp=plane((V){0,0,0},d,&tp);if(hs&&(!hp||ts<tp)){p=mul(d,ts);c=mul((V){1,.2,.2},shadow(p,l)?.2f:.2f+.8f*fmaxf(0,dot(n,l)));}else if(hp){p=mul(d,tp);c=(floorf(p.x)+floorf(p.z));c=mul((V){c-(int)c?.5f:.5f,c-(int)c?.5f:.5f,c-(int)c?.5f:.5f},shadow(p,l)?.2f:.2f+.8f*l.y);}else{float q=(d.y+1)*.5f;c=(V){1-.5f*q,1-.3f*q,1};}fprintf(f,"%d %d %d\n",pix(c.x),pix(c.y),pix(c.z));}}fprintf(stderr,"\nRendering complete\nWrote image to image.ppm\nDone.\n");fclose(f);return 0;}

